/**
 * Block schemas. A page is an ordered list of these blocks plus SEO metadata (see PageDefinition).
 * Every block is plain JSON so pages can be authored by hand or generated by the phase-2 agent.
 * See src/blocks/catalog.ts for "when to use" guidance per block.
 */

export type Cta = { label: string; href: string; style?: "primary" | "secondary"; arrow?: "right" | "down" };
export type ImageRef = { src: string; alt: string };
export type Tone = "light" | "surface" | "dark";

/** `bg` overrides a block's default section background (used to alternate light/dark rhythm). */
type Heading = { eyebrow?: string; heading?: string; intro?: string; bg?: Tone };
/** `anchor` makes the block a jump target (e.g. a hero CTA with href "#case-studies"). */
type Base = { id?: string; anchor?: string };

export type HeroBlock = Base & {
  type: "hero";
  variant: "dark" | "split" | "light";
  eyebrow?: string;
  title: string;
  /** A word inside `title` rendered in the accent colour. */
  accentWord?: string;
  /** Giant outlined ghost text behind the headline (dark variant). */
  watermark?: string;
  /** Hero stays fixed while the rest of the page scrolls over it (md+ screens only). */
  pinned?: boolean;
  subtitle?: string;
  ctas?: Cta[];
  badge?: { value: string; label: string };
  image?: ImageRef;
};

export type StatsBlock = Base &
  Heading & {
    type: "stats";
    tone?: "dark" | "light";
    /** split: heading on the left, intro paragraph on the right. */
    layout?: "stacked" | "split";
    items: { value: string; label: string; note?: string }[];
  };

export type CardGridBlock = Base &
  Heading & {
    type: "cardGrid";
    /** portrait: image-first people/team cards (4 columns, 2 on mobile). */
    variant?: "cards" | "portrait";
    columns?: 2 | 3 | 4;
    items: { title: string; body: string; href?: string; linkLabel?: string; tag?: string; image?: ImageRef }[];
  };

export type IconName =
  | "heart" | "brain" | "cash" | "headset" | "trend" | "bulb" | "laptop" | "shield"
  | "lock" | "globe" | "users" | "rocket" | "book" | "check" | "pie" | "award"
  | "code" | "cloud" | "data" | "sparkles";

export type IconGridBlock = Base &
  Heading & {
    type: "iconGrid";
    columns?: 2 | 3 | 4;
    tone?: "light" | "dark";
    items: { icon: IconName; title: string; body?: string }[];
  };

export type FeatureListBlock = Base &
  Heading & {
    type: "featureList";
    /** zigzag: alternating image/text rows with angled image masks. */
    variant?: "grid" | "zigzag";
    items: { title: string; body?: string; image?: ImageRef }[];
  };

export type TestimonialsBlock = Base &
  Heading & {
    type: "testimonials";
    /** carousel: scroll-snap slider; grid: review wall; spotlight: one giant quote + selectable list. */
    variant?: "carousel" | "grid" | "spotlight";
    limit?: number;
    /** grid: show this many first, then a "Show all" button. */
    initial?: number;
    /** carousel: heading/intro/cta in a left rail, one slide visible with arrows on top. */
    split?: boolean;
    cta?: Cta;
  };

export type CaseStudiesBlock = Base &
  Heading & {
    type: "caseStudies";
    filterable?: boolean;
    limit?: number;
    viewAll?: Cta;
  };

export type TabsBlock = Base &
  Heading & {
    type: "tabs";
    /** pills: horizontal tabs; rail: vertical rail on md+, accordion on mobile. */
    layout?: "pills" | "rail";
    tabs: {
      label: string;
      title: string;
      body: string;
      /** Optional tick-list shown in the panel. */
      points?: string[];
      quote?: { text: string; name: string; role: string };
      cta?: Cta;
    }[];
  };

export type JobsBlock = Base &
  Heading & {
    type: "jobs";
    featuredOnly?: boolean;
    /** Adds an "Apply" button to each job card. */
    applyLabel?: string;
    /** Footer row under the cards: text plus a button. */
    footer?: { text: string; cta: Cta };
    viewAll?: Cta;
  };

export type FaqBlock = Base &
  Heading & {
    type: "faq";
    /** Only one answer open at a time. */
    singleOpen?: boolean;
    items: { q: string; a: string }[];
  };

export type BadgesBlock = Base &
  Heading & {
    type: "badges";
    /** marquee: auto-scrolling strip (pauses on hover, static for reduced-motion users). */
    variant?: "grid" | "marquee";
    items: { name: string; label?: string }[];
  };

export type ProcessBlock = Base &
  Heading & {
    type: "process";
    steps: { title: string; body: string }[];
  };

export type RichTextBlock = Base &
  Heading & {
    type: "richText";
    paragraphs: string[];
    callout?: { title: string; body: string };
    /** Image beside the text. */
    media?: { image: ImageRef; side?: "left" | "right" };
    align?: "left" | "center";
    cta?: Cta;
  };

export type CtaBlock = Base & {
  type: "cta";
  eyebrow?: string;
  heading: string;
  body?: string;
  primary: Cta;
  secondary?: Cta;
};

export type CollageBlock = Base &
  Heading & {
    type: "collage";
    items: { caption: string; image?: ImageRef }[];
  };

export type LocationsBlock = Base &
  Heading & {
    type: "locations";
    items: { city: string; detail?: string }[];
  };

export type ContactBlock = Base &
  Heading & {
    type: "contact";
    details: { label: string; value: string; href?: string }[];
  };

export type Block =
  | HeroBlock | StatsBlock | CardGridBlock | IconGridBlock | FeatureListBlock
  | TestimonialsBlock | CaseStudiesBlock | TabsBlock | JobsBlock | FaqBlock
  | BadgesBlock | ProcessBlock | RichTextBlock | CtaBlock | CollageBlock
  | LocationsBlock | ContactBlock;

export type PageDefinition = {
  path: string; // "/" , "/about"
  /** TEMP: which site this layout was modelled on; shown as a badge (see ReferenceTag). */
  reference?: { name: string; url?: string };
  seo: {
    title: string;
    description: string;
    schemaType?: "WebPage" | "AboutPage" | "ContactPage" | "CollectionPage";
    noindex?: boolean;
    /** Optional short answer-style summary surfaced in llms.txt for AI search. */
    summary?: string;
  };
  blocks: Block[];
};
